// Recursive proxy to prevent any undefined crashes if an unexpected property is accessed
function createSafeProxy(target, path = '') {
  return new Proxy(target, {
    get(obj, prop) {
      if (typeof prop === 'symbol' || prop === 'inspect' || prop === 'prototype' || prop === 'then') {
        return obj[prop];
      }
      if (prop in obj) {
        const val = obj[prop];
        if (typeof val === 'object' && val !== null) {
          return createSafeProxy(val, path ? path + '.' + prop : prop);
        }
        return val;
      }
      // If property does not exist, return an empty proxy that can be stringified or nested
      const fallback = function() { return ''; };
      fallback.toString = () => '';
      fallback.valueOf = () => '';
      return createSafeProxy(fallback, path ? path + '.' + prop : prop);
    }
  });
}

